response:
[
  {
    "id": 1,
    "source": "Die 1 bitte, ohne Nachtisch.",
    "text": "شماره یک لطفاً، بدون دسر"
  },
  {
    "id": 2,
    "source": "So darf ich bitte mal, ich bin Arzt!\nMahlzeit!",
    "text": "ببخشید، میشه راه بدید، من دکترم!\nنوش جان"
  },
  {
    "id": 3,
    "source": "So, ich stell mich mal neben die beste\nMitarbeiterin meiner Abteilung,",
    "text": "خب، بذارید کنار بهترین کارمند\nبخش خودم بایستم"
  },
  {
    "id": 4,
    "source": "Ne, Herr Turculu?",
    "text": "مگه نه آقای تورچولو؟"
  },
  {
    "id": 5,
    "source": "- Na Tanja, alles klärchen?\n- Ja.",
    "text": "- خب تانیا، همه چی روبه‌راهه؟\n- آره"
  },
  {
    "id": 6,
    "source": "Ich hab' gehört mit Ihrem Freund\nist gerade Sendepause, hm?",
    "text": "شنیدم با دوست‌پسرت\nالان رابطه‌تون شکرآبه، هوم؟"
  },
  {
    "id": 7,
    "source": "Geht ja gar nicht voran hier!",
    "text": "اوضاع اصلاً اینجا پیش نمیره"
  },
  {
    "id": 8,
    "source": "Ich glaube, heute\nist der fiese Koch wieder da.",
    "text": "فکر کنم امروز\nاون آشپز عوضی دوباره برگشته"
  },
  {
    "id": 9,
    "source": "Ach der ist gut für Diäten, bei\ndem überlegt man sich zwei Mal,",
    "text": "ای بابا، برای رژیم خوبه، آدم پیش اون\nدو بار فکر می‌کنه"
  },
  {
    "id": 10,
    "source": "ob man zum Essen geht oder nicht.",
    "text": "که بره غذا بخوره یا نه"
  },
  {
    "id": 11,
    "source": "Ich trau mich auch nie,\nbei dem was zu sagen.",
    "text": "منم هیچ‌وقت جرئت نمی‌کنم\nچیزی بهش بگم"
  },
  {
    "id": 12,
    "source": "Den Letzten, der sich beschwert hat,\nhatten wir Dienstag als Gulasch.",
    "text": "نفر قبلی که اعتراض کرد رو\nسه‌شنبه به شکل خوراک گوشت خوردیم"
  }
]

[
  {
    "id": 1,
    "source": "Na ja, Führungsqualität\nheißt natürlich auch, sich",
    "text": "خب، مدیریت خوب\nیعنی آدم بتونه"
  },
  {
    "id": 2,
    "source": "mit schwierigen Mitarbeitern\nauseinandersetzen zu können.",
    "text": "با کارمندای دردسرساز\nکنار بیاد"
  },
  {
    "id": 3,
    "source": "Die Mitarbeiter fragen sich\ndoch vollkommen zurecht:",
    "text": "کارمندا هم کاملاً به حق\nاز خودشون می‌پرسن:"
  },
  {
    "id": 4,
    "source": "Hat der Chef Eier in der Hose?",
    "text": "رئیس اصلاً عرضه داره یا نه؟"
  },
  {
    "id": 5,
    "source": "Hat der Chef 'n Schwanz oder\nnur 'ne weiche Nudel?",
    "text": "رئیس مردِ عمله یا\nفقط یه آدمِ شل و ول؟"
  },
  {
    "id": 6,
    "source": "Ist doch so, Tanja, oder?",
    "text": "همینه دیگه، تانیا، مگه نه؟"
  },
  {
    "id": 7,
    "source": "[Titelmusik]",
    "text": "[موسیقی تیتراژ]"
  },
  {
    "id": 8,
    "source": "Ach und wenn’s geht,\nnur n’ ganz kleines Schnitzel!",
    "text": "آهان، اگه می‌شه\nیه شنیتسل خیلی کوچیک برام بذار"
  },
  {
    "id": 9,
    "source": "<i>[Koch]</i>\n<i>Die sind alle gleich groß.</i>",
    "text": "<i>[آشپز]</i>\n<i>همه‌شون یه اندازه‌ن</i>"
  },
  {
    "id": 10,
    "source": "- Könnte ich noch Erbsen kriegen?\n- Sind alle.",
    "text": "- می‌شه یه کم دیگه نخودفرنگی بدی؟\n- تموم شده"
  },
  {
    "id": 11,
    "source": "Meister, ich weiß nicht,\nob Sie früher in der Ostzone",
    "text": "استاد، نمی‌دونم\nقبلاً تو آلمان شرقی"
  },
  {
    "id": 12,
    "source": "gekocht haben,\naber mit dem Naziton",
    "text": "آشپزی می‌کردی یا نه،\nولی با این لحن نازی‌طور"
  },
  {
    "id": 13,
    "source": "kommen Sie hier nicht weit!",
    "text": "اینجا به جایی نمی‌رسی"
  }
]

[
  {
    "id": 1,
    "source": "Sie schon wieder, haben sich ja letzte\nWoche über meine Rouladen beschwert?",
    "text": "باز هم تو؟ هفته پیش بابت\nرولادهای من شکایت کرده بودی؟"
  },
  {
    "id": 2,
    "source": "Ich habe lediglich gesagt,\ndass in eine Roulade",
    "text": "من فقط گفتم\nکه توی رولاد"
  },
  {
    "id": 3,
    "source": "traditionell ein Gürkchen gehört.\nJedenfalls bei uns im freien Westen.",
    "text": "باید خیارشور باشه\nحداقل توی دنیای آزاد ما"
  },
  {
    "id": 4,
    "source": "Ein Gürkchen...",
    "text": "خیارشور..."
  },
  {
    "id": 5,
    "source": "Jetzt hören Sie mir mal zu,\nSie kleinliches Würstchen!",
    "text": "حالا خوب گوش کن ببین چی میگم\nسوسیسِ کوتوله و ایرادگیر"
  },
  {
    "id": 6,
    "source": "Ich quatsch' nicht in Ihren Job rein\nund Sie nicht in meinen, ja?!",
    "text": "من تو کار تو دخالت نمی‌کنم\nتو هم تو کار من دخالت نکن، فهمیدی؟"
  },
  {
    "id": 7,
    "source": "Und wenn Sie damit ein\nProblem haben, können wir uns gern",
    "text": "و اگه با این قضیه\nمشکلی داری، می‌تونیم"
  },
  {
    "id": 8,
    "source": "nach Dienstschluss\nauf’m Parkplatz treffen.",
    "text": "بعد از ساعت کاری\nتوی پارکینگ همدیگه رو ببینیم"
  },
  {
    "id": 9,
    "source": "Noch was?",
    "text": "چیز دیگه‌ای هست؟"
  },
  {
    "id": 10,
    "source": "<i>Das Leben ist kein Ponyhof.</i>\n<i>Auch bei einer Versicherung.</i>",
    "text": "<i>زندگی گل و بلبل نیست</i>\n<i>حتی توی یه شرکت بیمه</i>"
  },
  {
    "id": 11,
    "source": "{\\an8}Ich bin bestimmt toleranter als\ndie meisten hier in Führungspositionen",
    "text": "{\\an8}من قطعاً از خیلی از این مدیرها\nکه اینجا هستن، صبورترم"
  },
  {
    "id": 12,
    "source": "{\\an8}Aber auch mein Fass hat Grenzen.",
    "text": "{\\an8}ولی کاسه صبر منم حدی داره"
  },
  {
    "id": 13,
    "source": "Und wenn es da stetig reintropft,\ndann ist irgendwann der Boden raus.",
    "text": "و وقتی قطره‌قطره توش جمع بشه\nیه روزی تهش درمیاد"
  },
  {
    "id": 14,
    "source": "Das ist doch klar!",
    "text": "خب معلومه دیگه"
  },
  {
    "id": 15,
    "source": "[Telefon klingelt]",
    "text": "[صدای زنگ تلفن]"
  },
  {
    "id": 16,
    "source": "Heisterkamp?\nHallo?!",
    "text": "هایسترکامپ؟\nالو؟"
  },
  {
    "id": 17,
    "source": "[Telefon klingelt]",
    "text": "[صدای زنگ تلفن]"
  },
  {
    "id": 18,
    "source": "Ja, Heisterkamp. Hallo?",
    "text": "بله، هایسترکامپ. الو؟"
  },
  {
    "id": 19,
    "source": "So, das werden wir ja sehen.\nKleinliches Würstchen... Kantine.",
    "text": "خب، حالا می‌بینیم\nسوسیسِ کوتوله... سلف سرویس"
  },
  {
    "id": 20,
    "source": "Ja... Äh...\nMüller vom Gesundheitsamt, ähm,",
    "text": "بله... اممم...\nمولر هستم از اداره بهداشت، اممم"
  },
  {
    "id": 21,
    "source": "da kommen in letzter Zeit\neinige Beschwerden auf uns zu",
    "text": "اخیراً گزارش‌های زیادی\nبه دست ما رسیده"
  },
  {
    "id": 22,
    "source": "über ihre Kantine.\nSpeziell über Ihren Koch...",
    "text": "در مورد سلف سرویس شما\nمخصوصاً در مورد آشپزتون"
  },
  {
    "id": 23,
    "source": "Neulich wurde da sogar\neine kleine Maus gesehen!",
    "text": "حتی همین تازگی‌ها\nیه موش کوچولو اونجا دیده شده"
  },
  {
    "id": 24,
    "source": "Das finde ich aber auch, nicht?\nWiederhören!",
    "text": "منم همین فکر رو می‌کنم، نه؟\nخداحافظ"
  },
  {
    "id": 25,
    "source": "Wollen wir doch mal sehen,\nvon wegen <i>„kleinliches Würstchen“!</i>",
    "text": "حالا می‌بینیم\nکی <i>«سوسیسِ کوتوله»</i> است"
  }
]

[
  {
    "id": 1,
    "source": "Ich hatte Stress mit dem Koch\nin der Kantine.",
    "text": "با آشپز سلف\nبه مشکل خوردم"
  },
  {
    "id": 2,
    "source": "Aber Chef, die sehen ja\nIhre Nummer im Display.",
    "text": "ولی رئیس، اونا شماره شما رو\nرو صفحه تلفنشون می‌بینن"
  },
  {
    "id": 3,
    "source": "Na, Ihre Nummer steht doch\nbei denen im Display,",
    "text": "خب، شماره شما که\nرو صفحه اونا میفته"
  },
  {
    "id": 4,
    "source": "wenn Sie von hier aus anrufen…",
    "text": "وقتی از اینجا زنگ می‌زنید..."
  },
  {
    "id": 5,
    "source": "Ja klar, natürlich!",
    "text": "آره خب، معلومه"
  },
  {
    "id": 6,
    "source": "Die sollen doch nur sehen,\nwenn ich wollte, dass ich könnte.",
    "text": "فقط باید بفهمن که\nاگه بخوام، می‌تونم"
  },
  {
    "id": 7,
    "source": "So, was ist denn?",
    "text": "خب، چی شده؟"
  },
  {
    "id": 8,
    "source": "Ich sammel für\ndie Witwe vom Hilpers.",
    "text": "دارم برای بیوه\nهیلپرس پول جمع می‌کنم"
  },
  {
    "id": 9,
    "source": "- Wir wollten Ihr mal--\n- Das, ist mal eine gute Idee Erika.",
    "text": "- می‌خواستیم بهتون بگیم--\n- این دیگه یه فکر عالیه اریکا"
  },
  {
    "id": 10,
    "source": "Schlimme Sache,\ndas mit ihrem Hilpers.",
    "text": "خیلی ماجرای بدی بود،\nاون قضیه هیلپرس"
  },
  {
    "id": 11,
    "source": "Die arme Frau.\nSo.",
    "text": "زن بیچاره\nخب"
  },
  {
    "id": 12,
    "source": "Das ist ja alles\nwas Sie haben Chef!",
    "text": "رئیس، این کل چیزیه\nکه دارید!"
  },
  {
    "id": 13,
    "source": "Nehmen Sie ruhig alles!\nDas ist doch selbstverständlich…",
    "text": "همه‌شو بردارید، راحت باشید!\nخب این که وظیفه‌ست..."
  },
  {
    "id": 14,
    "source": "Danke schön, nehme ich gerne.",
    "text": "ممنونم، با کمال میل"
  },
  {
    "id": 15,
    "source": "In solchen Dingen zeigt sich dann,\nwer kleinlich ist und wer nicht.",
    "text": "تو همین چیزاست که معلوم می‌شه\nکی خسیسه و کی نیست"
  },
  {
    "id": 16,
    "source": "So, von wegen\n„kleinliches Würstchen“ und...",
    "text": "خب، در مورد اون\n«آدم کوته‌فکر» و..."
  },
  {
    "id": 17,
    "source": "Erika, warte Sie mal\neben ganz kurz!",
    "text": "اریکا، یه لحظه\nصبر کنید!"
  },
  {
    "id": 18,
    "source": "ich bin ja weiß Gott nicht nachtragend,\naber ich fände gut,",
    "text": "من خدا می‌دونه که کینه‌ای نیستم،\nولی به نظرم خوبه که"
  },
  {
    "id": 19,
    "source": "wenn bis auf Weiteres\ndie komplette Abteilung",
    "text": "تا اطلاع ثانوی\nکل بخش"
  },
  {
    "id": 20,
    "source": "die Kantine boykottieren würde.",
    "text": "سلف رو تحریم کنه"
  },
  {
    "id": 21,
    "source": "[sie lacht]",
    "text": "[می‌خندد]"
  },
  {
    "id": 22,
    "source": "Aber Chef, wäre das jetzt nicht\nein bisschen kleinlich?",
    "text": "ولی رئیس، این یه کم\nخسیس‌بازی نیست؟"
  },
  {
    "id": 23,
    "source": "Ich weiß nicht, was das\nmit kleinlich zu tun hat, Erika?!",
    "text": "نمی‌دونم این چه ربطی\nبه خسیس‌بازی داره، اریکا؟!"
  },
  {
    "id": 24,
    "source": "Wenn der dicke Hilpers stirbt,\ndann sind alle da,",
    "text": "وقتی هیلپرسِ چاق می‌میره،\nهمه حاضرن"
  },
  {
    "id": 25,
    "source": "aber wenn es gegen einen\nvon uns geht, der noch lebt,",
    "text": "ولی وقتی نوبت به یکی از\nماها می‌رسه که هنوز زنده‌ست،"
  }
]

[
  {
    "id": 1,
    "source": "dann ist Essig oder was?",
    "text": "پس یعنی همه‌چی کنسل، آره؟"
  },
  {
    "id": 2,
    "source": "Wenn Ihnen das so wichtig ist, dann\nheute eben nicht Kantine.",
    "text": "اگه این‌قدر براتون مهمه، پس\nامروز سلف تعطیل"
  },
  {
    "id": 3,
    "source": "So! Einer für alle, alle für einen!",
    "text": "خب! یکی برای همه، همه برای یکی"
  },
  {
    "id": 4,
    "source": "Kennen Sie nicht? Die Musketiere?\nEiner für alle, alle für einen?",
    "text": "نشنیدین؟ سه تفنگدار؟\nیکی برای همه، همه برای یکی؟"
  },
  {
    "id": 5,
    "source": "Ich interessier mich nicht\nso für Fußball.",
    "text": "من خیلی اهل\nفوتبال نیستم"
  },
  {
    "id": 6,
    "source": "[Bert macht Ploppgeräusche]",
    "text": "[برت صدای پلوپ درمی‌آورد]"
  },
  {
    "id": 7,
    "source": "...ja, weil's bei dir umgelegt...",
    "text": "...آره، چون واسه تو جابه‌جا شده..."
  },
  {
    "id": 8,
    "source": "[Bert ploppt weiterhin]",
    "text": "[برت همچنان صدای پلوپ درمی‌آورد]"
  },
  {
    "id": 9,
    "source": "[er macht ein Pferd nach]",
    "text": "[صدای اسب درمی‌آورد]"
  },
  {
    "id": 10,
    "source": "[steigt wieder auf Ploppen um]",
    "text": "[دوباره برمی‌گردد به صدای پلوپ]"
  },
  {
    "id": 11,
    "source": "Ja, sehr lustig...",
    "text": "آره، خیلی بامزه بود..."
  },
  {
    "id": 12,
    "source": "Achtung! Achtung!\nHier gibt es nichts zu sehen!",
    "text": "توجه! توجه!\nاینجا چیزی برای دیدن نیست"
  },
  {
    "id": 13,
    "source": "Das hier sind nicht Ernies Schuppen!",
    "text": "این‌ها شوره سر ارنی نیست"
  },
  {
    "id": 14,
    "source": "Ich wiederhole:\nDas sind nicht Ernies Schuppen!",
    "text": "تکرار می‌کنم:\nاین‌ها شوره سر ارنی نیست"
  },
  {
    "id": 15,
    "source": "Unabhängige Experten\nhaben das bestätigt...",
    "text": "کارشناس‌های مستقل\nاین رو تایید کردن..."
  },
  {
    "id": 16,
    "source": "Es kommt von der Farbe\nund der Größe her hin,",
    "text": "از نظر رنگ\nو اندازه شبیهه،"
  },
  {
    "id": 17,
    "source": "aber es ist nur Konfetti.\nVielen Dank für Ihre Aufmerksamkeit.",
    "text": "ولی فقط کاغذ رنگیه. ممنون از توجهتون"
  },
  {
    "id": 18,
    "source": "Ulf, ist das hier jetzt alles wieder...",
    "text": "اولف، این‌جا دوباره همه‌چی..."
  },
  {
    "id": 19,
    "source": "Das ist Verhinderung\nvon Arbeitszeit, sowas.",
    "text": "این کارا اتلاف\nوقت کاریه"
  },
  {
    "id": 20,
    "source": "{\\an8}Ich bin n’ Typ der auch mal aneckt,\nwie Che Guevara oder James Bond.",
    "text": "{\\an8}من آدمی‌ام که گاهی‌اوقات می‌زنه به سیم آخر،\nمثل چه گوارا یا جیمز باند"
  },
  {
    "id": 21,
    "source": "{\\an8}Ich war mal Klassensprecher\nin der Schule,",
    "text": "{\\an8}من یه زمانی تو مدرسه\nنماینده کلاس بودم"
  },
  {
    "id": 22,
    "source": "{\\an8}und ich fand auch damals\nschon Ordnung wichtig.",
    "text": "{\\an8}و از همون موقع‌ها هم\nنظم برام مهم بود"
  },
  {
    "id": 23,
    "source": "Und wenn die nicht eingehalten wurde,\ndann hab' ich das gemeldet.",
    "text": "و اگه کسی رعایت نمی‌کرد،\nمن گزارش می‌دادم"
  },
  {
    "id": 24,
    "source": "Das hat nichts mit petzen zu tun.\nDie anderen haben mich dann beim Sport",
    "text": "این اسمش خبرچینی نیست.\nبقیه‌ هم موقع ورزش"
  },
  {
    "id": 25,
    "source": "in den Basketballkorb gesetzt.\nAber das war mir egal.",
    "text": "منو می‌انداختن توی سبد بسکتبال.\nولی برام مهم نبود"
  }
]

[
  {
    "id": 1,
    "source": "Einmal nicht, da hatte ich so\nmit dem Magen, so eine Art Durchf...",
    "text": "یه بار نه، اون موقع یه مشکلی\nبا معده‌ام داشتم، یه جور اسها..."
  },
  {
    "id": 2,
    "source": "Was ist das?",
    "text": "این چیه؟"
  },
  {
    "id": 3,
    "source": "- Hase auf Motorrad!\n- Du Spinner!",
    "text": "- خرگوش رو موتور!\n- دیوونه‌ای تو!"
  },
  {
    "id": 4,
    "source": "Du, wir könnten ja vielleicht mal\nzusammen was Essen gehen oder so.",
    "text": "ببین، شاید بتونیم یه بار\nبا هم بریم یه چیزی بخوریم یا یه همچین چیزی"
  },
  {
    "id": 5,
    "source": "Also jetzt nicht hier Kantine,\nsondern irgendwie woanders...",
    "text": "یعنی نه اینجا تو سلف،\nیه جای دیگه..."
  },
  {
    "id": 6,
    "source": "Beim großen Parkhaus ist\nn’ Italiener, der soll ganz OK sein.",
    "text": "کنار پارکینگ بزرگ یه\nایتالیایی هست، میگن بد نیست"
  },
  {
    "id": 7,
